static void _nitro_desktop_err(NitroError* _out, const char* _name, const char* _message) {
    nitro_report_error(_name, _message, nullptr, nullptr);
    if (_out) {
        _out->hasError = 1;
        _out->name = _name ? strdup(_name) : nullptr;
        _out->message = _message ? strdup(_message) : nullptr;
        _out->code = nullptr;
        _out->stackTrace = nullptr;
    }
}

static uint8_t* _nitro_desktop_result_blob(uint8_t _tag, const NitroRecordWriter& _w) {
    int32_t _len = (int32_t)_w._buf.size();
    uint8_t* _out = (uint8_t*)malloc((size_t)(1 + 4 + _len));
    if (!_out) { return nullptr; }
    _out[0] = _tag;
    memcpy(_out + 1, &_len, 4);
    if (_len > 0) { memcpy(_out + 5, _w._buf.data(), (size_t)_len); }
    return _out;
}
static uint8_t* _nitro_desktop_result_err(const char* _msg) {
    NitroRecordWriter _w;
    _w.writeString(_msg ? std::string(_msg) : std::string());
    return _nitro_desktop_result_blob(1, _w);
}

